          )
        }
      >
        Export CSV
      </button>
""")
s=s.replace("import { ShowRetired, useShowRetired } from './ShowRetired';\n","import { downloadCsv } from './csv';\nimport { ShowRetired, useShowRetired } from './ShowRetired';\n")
